using System.Text.Json;using ToneCustoms.ShellStudio.Core;
namespace ToneCustoms.ShellStudio.Editor;
public enum TransformMode { Move, Rotate, Scale }
public sealed class EditorSession { readonly Stack<string> undo=[];readonly Stack<string> redo=[];public ShellProject Project {get;private set;}=new();public SceneObject? Selected {get;private set;}public TransformMode Mode {get;set;}=TransformMode.Move;public event Action? Changed;public void NewProject(string name){Project=new(){Name=name};Selected=null;undo.Clear();redo.Clear();Changed?.Invoke();}public void LoadProject(ShellProject p){Project=p;Selected=null;undo.Clear();redo.Clear();Changed?.Invoke();}void Snapshot(){undo.Push(JsonSerializer.Serialize(Project));redo.Clear();}public void Add(SceneObject o){Snapshot();Project.Objects.Add(o);Selected=o;Changed?.Invoke();}public void Select(Guid id){Selected=Project.Objects.FirstOrDefault(x=>x.Id==id);Changed?.Invoke();}public void BeforeMutation()=>Snapshot();public void DeleteSelected(){if(Selected==null)return;Snapshot();Project.Objects.Remove(Selected);Selected=null;Changed?.Invoke();}public SceneObject? DuplicateSelected(){if(Selected==null)return null;var p=Selected.Position;var c=new SceneObject{Name=Selected.Name+" Copy",Type=Selected.Type,Position=new(p.X+.25f,p.Y+.25f,p.Z),Rotation=new(Selected.Rotation.X,Selected.Rotation.Y,Selected.Rotation.Z),Scale=new(Selected.Scale.X,Selected.Scale.Y,Selected.Scale.Z),MaterialId=Selected.MaterialId,Collision=Selected.Collision,FloorLevel=Selected.FloorLevel};Add(c);return c;}public bool Undo(){if(undo.Count==0)return false;redo.Push(JsonSerializer.Serialize(Project));Project=JsonSerializer.Deserialize<ShellProject>(undo.Pop())??new();Selected=null;Changed?.Invoke();return true;}public bool Redo(){if(redo.Count==0)return false;undo.Push(JsonSerializer.Serialize(Project));Project=JsonSerializer.Deserialize<ShellProject>(redo.Pop())??new();Selected=null;Changed?.Invoke();return true;} }
